from functools import lru_cache
from itertools import combinations

def bits(x):
    while x:
        a=x&-x
        yield a
        x-=a

def sub(x,r):return [sum(c) for c in combinations(list(bits(x)),r)]
def norm(fs):
    fs=set(fs)
    return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))
def verts(fs):
    v=0
    for f in fs:v|=f
    return v
@lru_cache(None)
def cert(fs,k):
    if len(fs)==1:return ('simplex',)
    if not fs:return None
    m=fs[0].bit_count()
    if any(f.bit_count()!=m for f in fs):return None
    candidates=set()
    for f in fs:
        for r in range(1,min(m,k+1)+1):candidates.update(sub(f,r))
    for s in sorted(candidates,key=lambda s:(s.bit_count(),s)):
        D=norm([f for f in fs if f&s!=s]+[f^v for f in fs if f&s==s for v in bits(s)])
        if any(f.bit_count()!=m for f in D):continue
        L=norm(f^s for f in fs if f&s==s)
        if cert(D,k) is not None and cert(L,k) is not None:return s,D,L
    return None
@lru_cache(None)
def prefixes(fs,k):
    c=cert(fs,k)
    assert c is not None
    if c[0]=='simplex':return fs
    s,D,L=c
    return prefixes(D,k)+tuple(s|f for f in prefixes(L,k))
def isface(g,fs):return any(g&f==g for f in fs)

def complete(fs,k,nextbit=None):
    assert k>=1 and cert(fs,k) is not None
    m=fs[0].bit_count(); V=verts(fs)
    if nextbit is None:nextbit=V.bit_length()
    if m<=2:return (),tuple(f for f in sub(V,m) if f not in fs),nextbit
    if m==3:
        current=fs;order=[]
        # Close length-two paths in the 1-skeleton, introducing one edge.
        while True:
            found=False
            for f in sub(V,3):
                edges=sub(f,2)
                if sum(isface(e,current) for e in edges)==2:
                    current=tuple(sorted(current+(f,)));order.append(f)
                    found=True;break
            if not found:break
        assert all(isface(e,current) for e in sub(V,2))
        order.extend(f for f in sub(V,3) if f not in current)
        return (),tuple(order),nextbit
    apex=1<<nextbit;nextbit+=1
    L=norm(f^v for f in fs for v in bits(f))
    B,linkorder,nextbit=complete(L,k,nextbit)
    order=[apex|f for f in prefixes(L,k)]
    order.extend(apex|f for f in linkorder)
    W=V
    for b in B:W|=b
    order.extend(f for f in sub(W,m) if f not in fs)
    return (apex,)+B,tuple(order),nextbit

def verify(fs,k):
    A,order,_=complete(fs,k)
    assert len(A)==max(0,fs[0].bit_count()-3)
    current=fs
    for f in order:
        assert f not in current
        current=tuple(sorted(current+(f,)))
        assert cert(current,k) is not None
    W=verts(fs)
    for a in A:W|=a
    assert set(current)==set(sub(W,fs[0].bit_count()))
    return len(A),len(order)

